class HashTable {
private:
    int* table;
    int size;
    int loadFactor;

public:
    HashTable(int capacity) : size(10), loadFactor(0.75), table(new int[capacity]) {}

    void insert(int key, int value) {
        if (loadFactor > 0.5 && size >= table.length / 2) {
            resize();
        }
        int index = hash(key) % size;
        while (table[index] != 0) {
            index = (index + 1) % size;
        }
        table[index] = value;
    }

    int get(int key) {
        int index = hash(key) % size;
        while (table[index] == 0) {
            index = (index + 1) % size;
        }
        return table[index];
    }

    void printTable() {
        for (int i = 0; i < size; i++) {
            cout << "Bucket " << i << ": ";
            for (int j = 0; j < table[i].size(); j++) {
                cout << table[i][j] << " ";
            }
            cout << endl;
        }
    }

private:
    void resize() {
        int* newData = new int[size * 2];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < table[i].size(); j++) {
                newData[i * size + j] = table[i][j];
            }
        }
        delete[] table;
        table = newData;
    }

    int hash(int key) {
